import { Image } from 'react-native';

const KOBAN_STREAK_FLAME = require('../assets/general/streak.png');
const KOBAN_STREAK_FLAME_LOCKED = require('../assets/general/streak-locked.png');

// The big streak flame — the illustrated flame (assets/general/streak.png),
// not the earlier "on fire" cat mascot (assets/mascot/streak.png, still used
// elsewhere as a day-1/no-badge-art fallback — this component specifically
// was asked to switch to the plain flame illustration instead). Unlit uses a
// pre-baked grayscale twin (streak-locked.png, generated by desaturating the
// same source — same "earned = color art / locked = grayscale twin"
// convention STREAK_BADGE_ART/STREAK_BADGE_ART_LOCKED already use), rather
// than a differently-shaped placeholder — the two must read as the same
// flame, just unlit.
//
// The source art is a tall flame shape that only fills ~82.5% of its own
// square canvas height (measured via its alpha bounding box) — `size` is
// corrected (`/0.825`) so the VISIBLE flame renders at the requested size,
// not the frame around it (same lesson learned sizing the coin illustration
// — the frame isn't the icon).
const FILL_RATIO = 0.825;

export default function StreakFlameIcon({ size = 84, lit = true }) {
  const frame = size / FILL_RATIO;
  return (
    <Image
      source={lit ? KOBAN_STREAK_FLAME : KOBAN_STREAK_FLAME_LOCKED}
      style={{ width: frame, height: frame }}
      resizeMode="contain"
    />
  );
}
